function validate([customers]) {
  if (!Array.isArray(customers) || customers.length < 1 || customers.length > 100000) return 'customers needs 1 to 10^5 entries.';
  for (let i = 0; i < customers.length; i++) {
    const c = customers[i];
    if (!Array.isArray(c) || c.length !== 2) return 'Each customer is [arrival, time].';
    if (!c.every(v => Number.isInteger(v) && v >= 1 && v <= 10000)) return 'arrival and time are between 1 and 10^4.';
    if (i > 0 && c[0] < customers[i - 1][0]) return 'Arrival times must not decrease.';
  }
  return null;
}

