function averageWaitingTime(customers) {
  let finish = 0;
  let totalWait = 0;
  for (const [arrival, time] of customers) {
    const start = Math.max(finish, arrival);
    finish = start + time;
    totalWait += finish - arrival;
  }
  return totalWait / customers.length;
}

