function averageWaitingTime(customers) {
  // Dish i ends at the latest of: arrival[k] + time[k] + ... + time[i] over every k <= i.
  const n = customers.length;
  let sum = 0;
  for (let i = 0; i < n; i++) {
    let end = 0, cook = 0;
    for (let k = i; k >= 0; k--) {
      cook += customers[k][1];
      end = Math.max(end, customers[k][0] + cook);
    }
    sum += end - customers[i][0];
  }
  return sum / n;
}

