function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(1500, 2000) : pick(1, 8);
  const arrivalMax = size === 'large' ? 10000 : pick(1, 30);
  const timeMax = size === 'large' ? [10, 1000, 10000][pick(0, 2)] : pick(1, 10);
  const arrivals = Array.from({ length: n }, () => pick(1, arrivalMax)).sort((a, b) => a - b);
  return [arrivals.map(arrival => [arrival, pick(1, timeMax)])];
}
